import React from 'react'

import {
    Chart as ChartJS,
    ArcElement,
    Tooltip,
    Legend,
} from 'chart.js'

import { Doughnut } from 'react-chartjs-2'

ChartJS.register(
    ArcElement,
    Tooltip,
    Legend
)


function LoanTypeDistribution() {

    const loanTypes = [
        {
            name: 'Personal Loan',
            value: 25,
        },
        {
            name: 'Business Loan',
            value: 15,
        },
        {
            name: 'Home Loan',
            value: 12,
        },
        {
            name: 'Loan Against Property',
            value: 30,
        },
        {
            name: 'Education Loan',
            value: 5,
        },
        {
            name: 'Car Loan',
            value: 4,
        },
        {
            name: 'Gold Loan',
            value: 3,
        },
        {
            name: 'Credit Card',
            value: 4,
        },
        {
            name: 'Agricultural Loan',
            value: 2,
        },
    ]


    const total = loanTypes.reduce(
        (sum, item) => sum + item.value,
        0
    )


    const data = {
        labels: loanTypes.map(item => item.name),

        datasets: [
            {
                data: loanTypes.map(item => item.value),

                backgroundColor: loanTypes.map(
                    () => 'rgb(143, 212, 0)'
                ),

                borderColor: '#ffffff',

                borderWidth: 2,
            },
        ],
    }


    const options = {
        responsive: true,

        maintainAspectRatio: false,

        cutout: '65%',

        plugins: {
            legend: {
                display: false,
            },
        },
    }


    return (

        <div className="card bg-base-100 shadow-md">

            <div className="card-body">

                {/* Header */}
                <div className="flex items-center justify-between">

                    <div className="flex items-center gap-2">

                        <h2 className="card-title text-base">
                            Loan Type Distribution
                        </h2>

                        <span className="badge badge-success badge-outline">
                            Aug 2026
                        </span>

                    </div>

                </div>


                {/* Month selector */}

                <select className="select select-bordered select-sm w-full mt-3">

                    <option>Aug 2026</option>
                    <option>Jul 2026</option>
                    <option>Jun 2026</option>
                    <option>May 2026</option>

                </select>


                {/* Donut */}

                <div className="flex justify-center py-8">

                    <div className="relative w-52 h-52">

                        <Doughnut
                            data={data}
                            options={options}
                        />

                        {/* Center text */}

                        <div className="absolute inset-0 flex items-center justify-center pointer-events-none">

                            <div className="text-center">

                                <p className="text-xs text-base-content/50">
                                    Total
                                </p>

                                <p className="text-xl font-semibold">
                                    {total}
                                </p>

                            </div>

                        </div>

                    </div>

                </div>


                {/* Legend */}

                <div className="grid grid-cols-2 gap-x-4 gap-y-2">

                    {loanTypes.map((loan) => (

                        <div
                            key={loan.name}
                            className="flex items-center gap-2 text-xs"
                        >

                            <span
                                className="w-2 h-2 rounded-full shrink-0"
                                style={{
                                    backgroundColor: 'rgb(143, 212, 0)',
                                }}
                            />

                            <span className="truncate">
                                {loan.name}
                            </span>

                        </div>

                    ))}

                </div>


                {/* Footer */}

                <div className="divider"></div>

                <div className="flex justify-between items-center">

                    <div>

                        <p className="text-sm text-base-content/60">
                            Total Disbursed
                        </p>

                        <p className="text-xs text-base-content/40">
                            25 loans
                        </p>

                    </div>

                    <div
                        className="font-semibold"
                        style={{
                            color: 'rgb(143, 212, 0)',
                        }}
                    >
                        ₹172.66 L
                    </div>

                </div>

            </div>

        </div>
    )
}

export default LoanTypeDistribution
